import pandas as pd

df = pd.DataFrame({
    "order_id": [1, 2, 2, 4],
    "amount": [10.0, -5.0, 7.5, None],
    "status": ["paid", "paid", "refunded", "unknown"],
})

failures = []
if not df["order_id"].is_unique:
    failures.append("order_id is not unique")
if df["amount"].isna().any():
    failures.append("amount has missing values")
if (df["amount"] < 0).any():
    failures.append("amount has negative values")
if not df["status"].isin(["paid", "refunded"]).all():
    failures.append("status has unknown values")

print(len(failures), "check(s) failed")
for f in failures:
    print("-", f)

import pandas as pd

df = pd.DataFrame({
    "group": ["A"] * 4 + ["B"] * 4,
    "x": [1, 2, 3, 4, 6, 7, 8, 9],
    "y": [8, 9, 10, 11, 1, 2, 3, 4],
})

print("all rows:", round(df["x"].corr(df["y"]), 2))
for name, part in df.groupby("group"):
    print("group", name, round(part["x"].corr(part["y"]), 2))
